import requests

class ClaudeService:
    def __init__(self):
        from config import CLAUDE_KEY
        self.api_key = CLAUDE_KEY
        self.endpoint = "https://api.claude.com/v1"
        if not self.api_key:
            raise ValueError("Claude API key not configured")

    def call_model(self, payload):
        headers = {"Authorization": f"Bearer {self.api_key}"}
        return requests.post(self.endpoint, json=payload, headers=headers)

